import{z as i,x as A,o as t,c as d,q as o,j as s,D as E,d as B,s as l,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"文档数据库","description":"","frontmatter":{"title":"文档数据库","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/document-db.md","filePath":"cs/document-db.md","lastUpdated":1791413859000}'),p={name:"cs/document-db.md"};function m(c,a,C,D,h,u){const r=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="文档数据库" tabindex="-1">文档数据库 <a class="header-anchor" href="#文档数据库" aria-label="Permalink to &quot;文档数据库&quot;">​</a></h1><div class="epigraph"><p>文档是嵌套的自描述记录，默认一次读整图。二级索引与聚合管道补查询；跨文档事务曾是弱项，现正在往回补 SQL 课已有的东西。</p><footer>—— 据 Stonebraker 对文档；MongoDB 文档模型实践；阻抗失配对照</footer></div><p><a href="/cs/rocksdb">上一课</a>给了 KV LSM。本课把值变成 JSON/BSON 一类文档。缺口是数据模型：1NF 分解 vs 嵌套预连接。ORM 阻抗课的对象图在这里接近存储形状。不是「无 schema」——有 schema 演化与稀疏字段，约束弱于关系。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>嵌套数组：订单内行项目一次读出，免连接。更新一行项目可能重写整文档或用路径更新。缺口是<strong>粒度</strong>：文档太大则回表式读放大，太碎则又变关系。二级索引：对嵌套路径建 B+ 或 LSM 索引，写放大按路径。聚合：管道像受限的物理计划，优化器弱于 Selinger 全搜索。</p><p><span class="marginnote">直觉类比：文档模型像把整张快递单一页拿走——收件人、物品清单、运费都在一张纸上；关系模型是单据、包裹、客户分放三个抽屉，用时再对单拼齐。读多就整页拿走快，改多就分抽屉，免得整页重抄。</span></p><p>事务：早期单文档原子；多文档事务回到 2PL/MVCC 故事。分片键常是文档 id 或租户。</p><p><span class="marginnote">文档库不是向量库、不是图库。查询语言不是 SQL 全集。本课模型，不背某查询语法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建模：按读路径嵌套，按写冲突切文档。索引只盖过滤路径。与 CDC：oplog 是逻辑日志。与 Parquet：分析常倒出列文件，HTAP 新鲜度问题再现。</p><p>NULL 与缺字段：稀疏，与三值不同，查询要定义缺省。</p><p><span class="marginnote">数字实例：MongoDB 单文档上限 16 MB。把上千条评论全嵌进帖子文档，既逼近上限，又让每次新增评论都重写兆级文档。惯例是「低频小数据嵌套、高频大数据引用」：十来个标签直接嵌，几百条评论拆集合。</span></p>',12)),(t(),s(n,null,{default:E(()=>[l(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOC%5B%22%E5%B5%8C%E5%A5%97%E6%96%87%E6%A1%A3%22%5D%20--%3E%20GET%5B%22%E6%8C%89%20id%20%E4%B8%80%E6%AC%A1%E8%AF%BB%22%5D%0A%20%20DOC%20--%3E%20IDX%5B%22%E8%B7%AF%E5%BE%84%E4%BA%8C%E7%BA%A7%E7%B4%A2%E5%BC%95%22%5D%0A%20%20IDX%20--%3E%20FILT%5B%22%E8%BF%87%E6%BB%A4%E5%90%8E%E5%86%8D%E5%8F%96%E6%96%87%E6%A1%A3%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"存储常 LSM（WiredTiger、RocksDB）。覆盖：投影可只返回字段，延迟物化在文档内。计划回归：忘了索引变成全集合扫。",-1)),a[5]||(a[5]=e("p",null,"关系对照：连接存在但贵，鼓励反规范化——5NF 课的显式冗余，缺维护合同则漂移。",-1)),(t(),s(n,null,{default:E(()=>[l(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%80%E5%AF%B9%E5%A4%9A%E7%9A%84%E6%95%B0%E6%8D%AE%E8%A6%81%E6%80%8E%E4%B9%88%E5%AD%98%EF%BC%9F%22%5D%20--%3E%20E%5B%22%E5%B5%8C%E5%A5%97%E8%BF%9B%E7%88%B6%E6%96%87%E6%A1%A3%22%5D%0A%20%20E%20--%3E%20E1%5B%22%E4%B8%80%E6%AC%A1%E8%AF%BB%E5%87%BA%EF%BC%8C%E6%97%A0%E9%9C%80%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20E%20--%3E%20E2%5B%22%E5%AD%90%E9%A1%B9%E5%8D%95%E7%8B%AC%E6%94%B9%E5%88%99%E6%95%B4%E6%96%87%E6%A1%A3%E9%87%8D%E5%86%99%E6%94%BE%E5%A4%A7%22%5D%0A%20%20Q%20--%3E%20R%5B%22%E5%BC%95%E7%94%A8%E5%8F%A6%E4%B8%80%E9%9B%86%E5%90%88%22%5D%0A%20%20R%20--%3E%20R1%5B%22%E5%AD%90%E9%A1%B9%E7%8B%AC%E7%AB%8B%E6%9B%B4%E6%96%B0%EF%BC%8C%E7%B2%92%E5%BA%A6%E7%BB%86%22%5D%0A%20%20R%20--%3E%20R2%5B%22%E8%AF%BB%E8%A6%81%E5%A4%9A%E6%AC%A1%E5%BE%80%E8%BF%94%EF%BC%8C%E8%BF%91%E4%BC%BC%E5%85%B3%E7%B3%BB%E5%BA%93%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">常见误区：以为「无 schema」就不用设计数据。实际上约束从数据库转移到应用——字段名拼错不报错、同字段类型五花八门、迁移靠脚本扫全集合。建模难度没有消失，只是从「先定表结构」变成「先想清楚读写模式」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Bigtable 宽列。也不把文档当全文引擎——全文另倒排。图多跳文档嵌套表达差。</p><p>后课默认：读路径聚合用文档；多对多连接用关系或图。宽列 Bigtable：稀疏列族、行键设计，不是 JSON 树。</p><p>文档是预物化的外模式，内模式仍是页或 SST。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>文档嵌套服务一次读出；索引与多文档事务补关系能力。</li><li>过大过碎都失败；分析常外倒列存。</li><li>宽列 Bigtable 下一课。</li><li>出处：Stonebraker；文档库实践；阻抗课。</li></ul>',7))])}const f=i(p,[["render",m]]);export{_ as __pageData,f as default};
